(7, 'Mac', 'MacBook, Mac Studio và máy trạm hiệu năng cao', 'https://images.unsplash.com/photo-1517336714731-489689fd1ca8?auto=format&fit=crop&w=400&q=80'),
(8, 'iPhone', 'Điện thoại thông minh Titanium đỉnh cao', 'https://images.unsplash.com/photo-1592750475338-74b7b21085ab?auto=format&fit=crop&w=400&q=80'),
(9, 'iPad', 'Máy tính bảng màn hình Tandem OLED M4', 'https://images.unsplash.com/photo-1544244015-0df4b3ffc6b0?auto=format&fit=crop&w=400&q=80'),
