(11, 'Apple Vision Pro', 'Thiết bị điện toán không gian đột phá visionOS', 'https://images.unsplash.com/photo-1593508512255-86ab42a8e620?auto=format&fit=crop&w=400&q=80'),
(12, 'AirPods & Âm Thanh', 'Tai nghe chống ồn chủ động thích ứng và HomePod', 'https://images.unsplash.com/photo-1546435770-a3e426bf472b?auto=format&fit=crop&w=400&q=80'),
(13, 'Màn Hình & Phụ Kiện', 'Studio Display 5K, Pro Display XDR và phụ kiện', 'https://images.unsplash.com/photo-1527443224154-c4a3942d3acf?auto=format&fit=crop&w=400&q=80')
INSERT INTO products (id, store_id, category_id, name, subname, description, base_price, image_url, hover_image_url, sku, stock, rating, reviews, badge, status, created_at, updated_at) VALUES 
(1, 1, 11, 'Apple Vision Pro', 'Điện toán không gian 512GB', 'Giải phóng không gian làm việc và giải trí với hệ điều hành visionOS trực quan, kiểm soát bằng mắt, tay và giọng nói.', 3499, 'https://images.unsplash.com/photo-1593508512255-86ab42a8e620?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1592478411213-6153e4ebc07d?auto=format&fit=crop&w=800&q=80', 'AP-VISPRO-M2', 5, 4.9, 428, 'Mới Nhất', 'ACTIVE', NOW(), NOW()),
(2, 1, 2, 'MacBook Pro 16"', 'M3 Max • 64GB RAM • 1TB SSD', 'Hiệu năng đột phá từ vi xử lý M3 Max thế giới, màn hình Liquid Retina XDR với thời lượng pin lên đến 22 giờ liên tục.', 3999, 'https://images.unsplash.com/photo-1517336714731-489689fd1ca8?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1611186871348-b1ce696e52c9?auto=format&fit=crop&w=800&q=80', 'MB-M3MAX-64', 3, 5, 812, 'Hiệu Năng Đỉnh Cao', 'ACTIVE', NOW(), NOW()),
(3, 1, 3, 'B&O Beoplay H95', 'Tai nghe chống ồn Hi-Res đỉnh cao', 'Tai nghe over-ear chống ồn chủ động thích ứng thủ công tinh xảo, củ loa titanium 40mm với chất âm nguyên bản.', 999, 'https://images.unsplash.com/photo-1546435770-a3e426bf472b?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1505740420928-5e560c06d30e?auto=format&fit=crop&w=800&q=80', 'BO-H95-INDIGO', 8, 4.8, 194, 'Chế Tác Thủ Công', 'ACTIVE', NOW(), NOW()),
(4, 1, 4, 'Herman Miller Embody', 'Ghế công thái học chuyên biệt Gaming', 'Công nghệ nâng đỡ cột sống Pixelated Support tự điều chỉnh theo vi chuyển động của cơ thể, tản nhiệt bề mặt tối ưu.', 1795, 'https://images.unsplash.com/photo-1580481077195-c328ad4f447a?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1505797149-43b0069ec26b?auto=format&fit=crop&w=800&q=80', 'HM-EMBODY-BLK', 2, 4.9, 650, 'Bảo Hành 12 Năm', 'ACTIVE', NOW(), NOW()),
(5, 1, 5, 'Leica Q3 Titanium', 'Cảm biến 60MP • Summilux 28mm f/1.7', 'Ống kính cố định huyền thoại Summilux 28mm f/1.7 kết hợp cảm biến Full-Frame BSI CMOS 60 triệu điểm ảnh.', 6295, 'https://images.unsplash.com/photo-1516035069371-29a1b244cc32?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1502920917128-1aa500764cbd?auto=format&fit=crop&w=800&q=80', 'LEI-Q3-TITAN', 1, 5, 88, 'Limited Edition', 'ACTIVE', NOW(), NOW()),
(6, 1, 6, 'Keychron Q1 Pro', 'Bàn phím nhôm CNC QMK/VIA Không Dây', 'Thiết kế Double-Gasket Mount chống ồn, kết nối không dây Bluetooth 5.1 và núm xoay đa nhiệm bằng nhôm nguyên khối.', 219, 'https://images.unsplash.com/photo-1618384887929-16ec33fab9ef?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1587829741301-dc798b83add3?auto=format&fit=crop&w=800&q=80', 'KC-Q1PRO-GAT', 13, 4.7, 412, 'Hot Seller', 'ACTIVE', NOW(), NOW()),
(7, 1, 11, 'Hộp Du Lịch Apple Vision Pro', 'Bảo vệ thiết bị khi di chuyển', 'Thiết kế ôm khít lớp vỏ đệm polycarbonate chống va đập, ngăn chứa pin và phụ kiện gọn gàng.', 199, 'https://images.unsplash.com/photo-1553062407-98eeb64c6a62?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1544816155-12df9643f363?auto=format&fit=crop&w=800&q=80', 'AP-VISPRO-CASE', 18, 4.8, 92, 'Phụ Kiện', 'ACTIVE', NOW(), NOW()),
(8, 1, 7, 'MacBook Pro 16" M3 Max', 'Chip M3 Max • 64GB RAM • 1TB SSD', 'Sức mạnh vô đối cho dựng phim 8K và tính toán AI. Màn hình Liquid Retina XDR sáng 1600 nits, pin 22 giờ.', 3999, 'https://images.unsplash.com/photo-1517336714731-489689fd1ca8?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1611186871348-b1ce696e52c9?auto=format&fit=crop&w=800&q=80', 'MB-M3MAX-16', 4, 5, 812, 'Hiệu Năng Đỉnh Cao', 'ACTIVE', NOW(), NOW()),
(9, 1, 7, 'MacBook Pro 14" M3 Pro', 'Chip M3 Pro • 18GB RAM • 512GB SSD', 'Sự kết hợp hoàn hảo giữa kích thước cơ động và sức mạnh đồ họa Pro. Hoàn thiện màu Space Black sang trọng.', 1999, 'https://images.unsplash.com/photo-1541807084-5c52b6b3adef?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1517336714731-489689fd1ca8?auto=format&fit=crop&w=800&q=80', 'MB-M3PRO-14', 8, 4.9, 640, 'Phổ Biến Nhất', 'ACTIVE', NOW(), NOW()),
(10, 1, 7, 'MacBook Air 15" M3', 'Mỏng 11.5mm • Màn hình 15.3 inch', 'Màn hình Liquid Retina rộng rãi, thiết kế siêu mỏng nhẹ không quạt hoàn toàn yên tĩnh, pin 18 giờ.', 1299, 'https://images.unsplash.com/photo-1629654297299-c8506221ca97?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1517336714731-489689fd1ca8?auto=format&fit=crop&w=800&q=80', 'MBA-M3-15', 12, 4.9, 930, 'Mới', 'ACTIVE', NOW(), NOW()),
(11, 1, 7, 'MacBook Air 13" M3', 'Siêu nhẹ 1.24kg • Màu Midnight', 'Chiếc laptop được yêu thích nhất thế giới nay còn nhanh hơn với chip M3, hỗ trợ xuất 2 màn hình ngoài.', 1099, 'https://images.unsplash.com/photo-1531297484001-80022131f5a1?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1629654297299-c8506221ca97?auto=format&fit=crop&w=800&q=80', 'MBA-M3-13', 16, 4.8, 1240, 'Bán Chạy', 'ACTIVE', NOW(), NOW()),
(12, 1, 7, 'Mac Studio M2 Ultra', '24-core CPU • 76-core GPU • 192GB RAM', 'Cỗ máy trạm mạnh mẽ bậc nhất dành cho các phòng thu âm thanh, dựng phim Hollywood và mô hình ngôn ngữ lớn.', 3999, 'https://images.unsplash.com/photo-1527443224154-c4a3942d3acf?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1517336714731-489689fd1ca8?auto=format&fit=crop&w=800&q=80', 'MS-M2ULTRA', 3, 5, 185, 'Pro Workstation', 'ACTIVE', NOW(), NOW()),
(13, 1, 7, 'Mac mini M2 Pro', 'Kích thước nhỏ gọn 19.7cm', 'Sức mạnh cấp chuyên nghiệp trong thân hình khối vuông tối giản, cổng kết nối đa dạng Thunderbolt 4.', 1299, 'https://images.unsplash.com/photo-1544816155-12df9643f363?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1527443224154-c4a3942d3acf?auto=format&fit=crop&w=800&q=80', 'MM-M2PRO', 7, 4.8, 310, 'Giá Tốt', 'ACTIVE', NOW(), NOW()),
(14, 1, 8, 'iPhone 16 Pro Max', 'Titan Sa Mạc • Màn hình 6.9" Super Retina XDR', 'Khung viền Titan cấp 5 siêu nhẹ, nút Điều Khiển Camera cảm ứng lực mới, camera Fusion 48MP zoom quang 5x.', 1199, 'https://images.unsplash.com/photo-1592750475338-74b7b21085ab?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1510557880182-3d4d3cba35a5?auto=format&fit=crop&w=800&q=80', 'IP-16PM-256', 10, 5, 2450, 'Flagship Mới', 'ACTIVE', NOW(), NOW()),
(15, 1, 8, 'iPhone 16 Pro', 'Titan Tự Nhiên • Màn hình 6.3"', 'Hiệu năng bứt phá với chip A18 Pro, thời lượng pin tăng vọt, hệ thống tản nhiệt graphene cao cấp.', 999, 'https://images.unsplash.com/photo-1510557880182-3d4d3cba35a5?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1592750475338-74b7b21085ab?auto=format&fit=crop&w=800&q=80', 'IP-16P-128', 14, 4.9, 1890, 'Mới Nhất', 'ACTIVE', NOW(), NOW()),
(16, 1, 8, 'iPhone 16', 'Màu Xanh Lưu Ly (Ultramarine)', 'Mặt lưng kính pha màu nguyên khối bền bỉ, chip A18 hỗ trợ Apple Intelligence, nút Tác Vụ đa nhiệm.', 799, 'https://images.unsplash.com/photo-1565849904461-04a58ad377e0?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1510557880182-3d4d3cba35a5?auto=format&fit=crop&w=800&q=80', 'IP-16-128', 22, 4.8, 1420, 'Màu Sắc Mới', 'ACTIVE', NOW(), NOW()),
(17, 1, 8, 'Ốp Lưng MagSafe Trong Suốt iPhone 16 Pro', 'Tích hợp nút điều khiển sapphire', 'Vật liệu polycarbonate chống ố vàng cao cấp, nam châm tích hợp sạc không dây chuẩn xác.', 49, 'https://images.unsplash.com/photo-1601784551446-20c9e07cdbdb?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1592750475338-74b7b21085ab?auto=format&fit=crop&w=800&q=80', 'IP-CASE-CLEAR', 45, 4.7, 530, 'Phụ Kiện', 'ACTIVE', NOW(), NOW()),
(18, 1, 9, 'iPad Pro 13" M4', 'Ultra Retina Tandem OLED • Mỏng 5.1mm', 'Chiếc máy mỏng nhất Apple từng sản xuất. Màn hình OLED hai lớp độ tương phản vô hạn, chip M4 đỉnh cao.', 1299, 'https://images.unsplash.com/photo-1544244015-0df4b3ffc6b0?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1561154464-82e9adf32764?auto=format&fit=crop&w=800&q=80', 'IPAD-PRO-13', 6, 5, 780, 'Siêu Mỏng', 'ACTIVE', NOW(), NOW()),
(19, 1, 9, 'iPad Air 11" M2', 'Chip M2 • Màn hình Liquid Retina', 'Hiệu năng đột phá cho sáng tạo nội dung, hỗ trợ Apple Pencil Pro và Magic Keyboard nổi.', 599, 'https://images.unsplash.com/photo-1561154464-82e9adf32764?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1544244015-0df4b3ffc6b0?auto=format&fit=crop&w=800&q=80', 'IPAD-AIR-11', 15, 4.9, 950, 'Bán Chạy', 'ACTIVE', NOW(), NOW()),
(20, 1, 9, 'Apple Pencil Pro', 'Cảm biến bóp nhạy • Phản hồi rung haptic', 'Cảm biến xoay thân bút Barrel Roll, chạm hai lần chuyển công cụ, tìm kiếm qua Find My tiện lợi.', 129, 'https://images.unsplash.com/photo-1588702547919-26089e690ecc?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1544244015-0df4b3ffc6b0?auto=format&fit=crop&w=800&q=80', 'PENCIL-PRO', 25, 4.9, 1100, 'Phụ Kiện', 'ACTIVE', NOW(), NOW()),
(21, 1, 10, 'Apple Watch Ultra 2', 'Titan Đen • Chống nước 100m', 'Vỏ titan đen mạ PVD chống trầy cực hạn, màn hình sáng 3000 nits, GPS tần số kép chuẩn xác nhất.', 799, 'https://images.unsplash.com/photo-1508685096489-7aacd43bd3b1?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1523275335684-37898b6baf30?auto=format&fit=crop&w=800&q=80', 'AW-ULTRA2-BLK', 5, 5, 940, 'Độ Bền Quân Đội', 'ACTIVE', NOW(), NOW()),
(22, 1, 10, 'Apple Watch Series 10', 'Nhôm Đen Bóng (Jet Black) • Mỏng nhất', 'Màn hình OLED góc nhìn rộng lớn hơn 30%, sạc nhanh 80% chỉ trong 30 phút, phát hiện chứng ngưng thở khi ngủ.', 399, 'https://images.unsplash.com/photo-1523275335684-37898b6baf30?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1508685096489-7aacd43bd3b1?auto=format&fit=crop&w=800&q=80', 'AW-S10-JETBLK', 14, 4.9, 1320, 'Mới', 'ACTIVE', NOW(), NOW()),
(23, 1, 10, 'Dây Đeo Milanese Loop Titan Tự Nhiên', 'Lưới đan titan dệt thủ công', 'Khóa nam châm tùy chỉnh vô cấp ôm vừa vặn mọi cổ tay, chống mồ hôi và chống ăn mòn nước biển.', 199, 'https://images.unsplash.com/photo-1522335789203-aabd1fc54bc9?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1508685096489-7aacd43bd3b1?auto=format&fit=crop&w=800&q=80', 'AW-STRAP-MILAN', 30, 4.8, 410, 'Phụ Kiện', 'ACTIVE', NOW(), NOW()),
(24, 1, 12, 'AirPods Max (USB-C)', 'Màu Midnight • Âm thanh Spatial Audio', 'Cổng sạc USB-C mới, màng loa dynamic 40mm chống méo tiếng, đệm tai dạng lưới thoáng khí tuyệt đối.', 549, 'https://images.unsplash.com/photo-1546435770-a3e426bf472b?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1505740420928-5e560c06d30e?auto=format&fit=crop&w=800&q=80', 'AP-MAX-USBC', 9, 4.8, 1680, 'Audiophile', 'ACTIVE', NOW(), NOW()),
(25, 1, 12, 'AirPods Pro 2 (USB-C)', 'Khử tiếng ồn chủ động gấp 2 lần', 'Chip H2 tối tân, tính năng Nhận biết Cuộc trò chuyện, bài kiểm tra thính lực đạt chuẩn lâm sàng.', 249, 'https://images.unsplash.com/photo-1600294037681-c80b4cb5b434?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1505740420928-5e560c06d30e?auto=format&fit=crop&w=800&q=80', 'AP-PRO2-USBC', 28, 4.9, 3890, 'Bán Chạy Nhất', 'ACTIVE', NOW(), NOW()),
(26, 1, 12, 'AirPods 4', 'Thiết kế mở ôm khít • Chống ồn chủ động', 'Lần đầu tiên tính năng khử ồn ANC xuất hiện trên thiết kế tai nghe mở, hộp sạc nhỏ gọn nhất lịch sử.', 179, 'https://images.unsplash.com/photo-1572536147248-ac59a8abfa4b?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1600294037681-c80b4cb5b434?auto=format&fit=crop&w=800&q=80', 'AP-4-ANC', 35, 4.8, 2100, 'Mới', 'ACTIVE', NOW(), NOW()),
(27, 1, 12, 'HomePod (Thế hệ 2)', 'Loa thông minh Midnight • Âm thanh vòm', 'Củ loa trầm hành trình dài, 5 loa tweeter dạng chùm, cảm biến nhiệt độ và độ ẩm thông minh trong phòng.', 299, 'https://images.unsplash.com/photo-1543512214-318c7553f230?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1546435770-a3e426bf472b?auto=format&fit=crop&w=800&q=80', 'HOMEPOD-GEN2', 11, 4.7, 510, 'Smart Home', 'ACTIVE', NOW(), NOW()),
(28, 1, 13, 'Apple Studio Display 27"', 'Độ phân giải 5K • Kính Nano-texture', 'Màn hình Retina 5K 14.7 triệu điểm ảnh, camera Ultra Wide 12MP căn giữa Center Stage, hệ thống 6 loa phòng thu.', 1899, 'https://images.unsplash.com/photo-1527443224154-c4a3942d3acf?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1517336714731-489689fd1ca8?auto=format&fit=crop&w=800&q=80', 'SD-5K-NANO', 4, 4.9, 320, '5K Retina', 'ACTIVE', NOW(), NOW()),
(29, 1, 13, 'Bàn Phím Magic Keyboard Touch ID', 'Bàn phím số mở rộng • Màu Đen Bạc', 'Cảm biến vân tay Touch ID đăng nhập nhanh và thanh toán Apple Pay bảo mật, cổng sạc USB-C dệt dù cao cấp.', 199, 'https://images.unsplash.com/photo-1587829741301-dc798b83add3?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1618384887929-16ec33fab9ef?auto=format&fit=crop&w=800&q=80', 'MK-TOUCHID-NUM', 20, 4.8, 890, 'USB-C Mới', 'ACTIVE', NOW(), NOW())
